	env.ValidateCheckpoint(CheckpointValidation{
		CheckpointID:              checkpointIDsAfter[1],
		Strategy:                  "manual-commit",
		FilesTouched:              []string{"partial.go"},
		ExpectedTranscriptContent: []string{"partial.go"},
	})
