// filesChangedInCommit returns the set of files changed in a commit by diffing against its parent.
func filesChangedInCommit(commit *object.Commit) map[string]struct{} {
	result := make(map[string]struct{})

	commitTree, err := commit.Tree()
	if err != nil {
		return result
	}

	var parentTree *object.Tree
	if commit.NumParents() > 0 {
		parent, err := commit.Parent(0)
		if err != nil {
			return result
		}
		parentTree, err = parent.Tree()
		if err != nil {
			return result
		}
	}

	if parentTree == nil {
		// Initial commit — all files are new
		if iterErr := commitTree.Files().ForEach(func(f *object.File) error {
			result[f.Name] = struct{}{}
			return nil
		}); iterErr != nil {
			return result
		}
		return result
	}

	changes, err := parentTree.Diff(commitTree)
	if err != nil {
		return result
	}
	for _, change := range changes {
		name := change.To.Name
		if name == "" {
			name = change.From.Name
		}
		result[name] = struct{}{}
	}
	return result
}

	// Write checkpoint metadata using the checkpoint store
	// Pass both TranscriptPath (for writeTranscript fallback when Transcript is empty,
	// e.g., carry-forward scenario) and SessionTranscriptPath (for metadata storage).
	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
		CheckpointID:                checkpointID,
		SessionID:                   state.SessionID,
		Strategy:                    StrategyNameManualCommit,
		Branch:                      branchName,
		Transcript:                  sessionData.Transcript,
