				]
			}`,
			expected: []string{"First prompt", "Second prompt"},
		},
		{
			name:      "Gemini no user messages",
			agentType: agent.AgentTypeGemini,
			content: `{
				"messages": [
					{"type": "gemini", "content": "Hello!"}
				]
