// hasSignificantContentOverlap checks if two file contents share significant lines.
// Returns true if the contents share at least one non-trivial line (>= 10 chars after trimming).
// This distinguishes partial staging (user kept some agent content) from
// "reverted and replaced" (user wrote completely different content).
func hasSignificantContentOverlap(content1, content2 string) bool {
	// Build set of significant lines from content2
	lines2 := strings.Split(content2, "\n")
	significantLines := make(map[string]bool)
	for _, line := range lines2 {
		trimmed := strings.TrimSpace(line)
		// Skip trivial lines (empty, very short, or common boilerplate)
		if len(trimmed) >= 10 && !isTrivialLine(trimmed) {
			significantLines[trimmed] = true
		}
	}

	if len(significantLines) == 0 {
		// No significant lines in content2, fall back to accepting any file overlap
		return true
	}

	// Check if any significant line from content1 matches
	lines1 := strings.Split(content1, "\n")
	for _, line := range lines1 {
		trimmed := strings.TrimSpace(line)
		if significantLines[trimmed] {
			return true // Found a matching significant line
		}
	}

	return false
}

