// hasSignificantContentOverlap checks if two file contents share significant lines.
// Returns true if the contents share at least one non-trivial line (>= 10 chars after trimming).
// This distinguishes partial staging (user kept some agent content) from
// "reverted and replaced" (user wrote completely different content).
func hasSignificantContentOverlap(content1, content2 string) bool {
	// Build set of significant lines from content2 (shadow/agent content)
	lines2 := strings.Split(content2, "\n")
	significantLines2 := make(map[string]bool)
	for _, line := range lines2 {
		trimmed := strings.TrimSpace(line)
		// Skip trivial lines (empty, very short, or common boilerplate)
		if len(trimmed) >= 10 && !isTrivialLine(trimmed) {
			significantLines2[trimmed] = true
		}
	}

	// Build set of significant lines from content1 (staged/user content)
	lines1 := strings.Split(content1, "\n")
	significantLines1 := make(map[string]bool)
	for _, line := range lines1 {
		trimmed := strings.TrimSpace(line)
		if len(trimmed) >= 10 && !isTrivialLine(trimmed) {
			significantLines1[trimmed] = true
		}
	}

	// If both contents have no significant lines (e.g., minimal boilerplate files),
	// fall back to hash comparison which is handled by caller (hashes don't match,
	// so we'd be here). Since hashes differ but no significant lines to compare,
	// treat as no overlap (files are functionally different).
	if len(significantLines2) == 0 && len(significantLines1) == 0 {
		// Both files have only trivial content but hashes differ.
		// The files are different (could be whitespace, braces, etc).
		// Conservative: don't treat as overlap.
		return false
	}

	// If shadow has significant lines but staged doesn't, no overlap.
	// User trimmed the file down to just boilerplate.
	if len(significantLines2) > 0 && len(significantLines1) == 0 {
		return false
	}

	// If shadow has no significant lines but staged does, no overlap.
	// User added significant content that wasn't from the agent.
	if len(significantLines2) == 0 && len(significantLines1) > 0 {
		return false
	}

	// Both have significant lines - check for overlap
	for line := range significantLines1 {
		if significantLines2[line] {
			return true // Found a matching significant line
		}
	}

	return false
}

// isTrivialLine returns true for lines that are common boilerplate and shouldn't count as overlap.
func isTrivialLine(line string) bool {
	trivialPatterns := []string{
		"package ",
		"import ",
		"import (",
		")",
		"{",
		"}",
		"func ",
		"return",
	}
	for _, pattern := range trivialPatterns {
		if strings.HasPrefix(line, pattern) || line == pattern {
			return true
		}
	}
	return false
}

