	state := &SessionState{
		SessionID:                   "test-session-token-usage",
		BaseCommit:                  "abc123def456",
		StartedAt:                   time.Now(),
		StepCount:                   5,
		CheckpointTranscriptStart:   42,
		TranscriptIdentifierAtStart: "test-uuid-abc123",
		TokenUsage: &agent.TokenUsage{
			InputTokens:         1000,
			CacheCreationTokens: 200,
			CacheReadTokens:     300,
			OutputTokens:        500,
