// TestE2E_ExistingFiles_RevertModification tests content-aware overlap detection
// when user reverts agent's modification to an existing file and makes their own changes.
func TestE2E_ExistingFiles_RevertModification(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t, "manual-commit")

	// Create and commit an existing file
	originalContent := `package main

func Calculate(x, y int) int {
	return x + y
}
`
	env.WriteFile("calc.go", originalContent)
	env.GitCommitWithShadowHooks("Add calculator", "calc.go")

	// Agent modifies the file
	t.Log("Agent modifying calc.go")
	prompt := `Modify calc.go to add a Multiply function that multiplies two integers.
Keep the existing Calculate function. Only modify this file.`

	result, err := env.RunAgent(prompt)
	require.NoError(t, err)
	AssertAgentSuccess(t, result, err)

	// Verify agent modified the file
	modifiedContent := env.ReadFile("calc.go")
	assert.Contains(t, modifiedContent, "Multiply", "calc.go should have Multiply function")

	// User reverts to original and writes completely different changes
	t.Log("User reverting and writing different changes")
	userContent := `package main

func Calculate(x, y int) int {
	return x + y
}

func Subtract(x, y int) int {
