// TestE2E_ExistingFiles_RevertModification tests content-aware overlap detection
// when user reverts agent's modification to an existing file and makes their own changes.
//
// IMPORTANT: For content-aware detection to prevent a checkpoint, the user's content
// must have NO significant overlap with the agent's content. If they share any
// non-trivial lines (like the original function), it counts as overlap.
func TestE2E_ExistingFiles_RevertModification(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t, "manual-commit")

	// Create and commit an existing file with MINIMAL content
	// so that when user replaces it, there's truly no overlap
	originalContent := `package main

// placeholder
`
	env.WriteFile("calc.go", originalContent)
	env.GitCommitWithShadowHooks("Add placeholder", "calc.go")

	// Agent REPLACES the file with completely new content
	t.Log("Agent replacing calc.go with new content")
	prompt := `Replace the contents of calc.go with this exact code:
package main

func AgentMultiply(a, b int) int {
	return a * b
}

func AgentDivide(a, b int) int {
	if b == 0 {
		return 0
	}
	return a / b
}

Only modify calc.go, nothing else.`

	result, err := env.RunAgent(prompt)
	require.NoError(t, err)
	AssertAgentSuccess(t, result, err)

	// Verify agent modified the file
	modifiedContent := env.ReadFile("calc.go")
	assert.Contains(t, modifiedContent, "AgentMultiply", "calc.go should have AgentMultiply function")

	// User reverts and writes COMPLETELY DIFFERENT content (no shared significant lines)
	t.Log("User reverting and writing completely different content")
	userContent := `package main

func UserAdd(x, y int) int {
	return x + y
}

func UserSubtract(x, y int) int {
	return x - y
}
`
	env.WriteFile("calc.go", userContent)

	// User commits their changes (not the agent's)
	t.Log("Committing user's changes")
	env.GitCommitWithShadowHooks("Add user functions", "calc.go")

	// Content-aware detection should prevent checkpoint trailer
	// because user's content has NO significant overlap with agent's content
	// (different function names, different implementations)
	checkpointIDs := env.GetAllCheckpointIDsFromHistory()
	t.Logf("Checkpoint IDs: %v", checkpointIDs)

	// The commit should NOT have a checkpoint trailer because the content
	// is completely different from what the agent wrote
	latestCheckpoint := env.GetLatestCheckpointID()
	assert.Empty(t, latestCheckpoint,
		"Content-aware detection should prevent checkpoint when user writes completely different content")
}

