func (s *ManualCommitStrategy) SaveChanges(ctx SaveContext) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Extract session ID from metadata dir
	sessionID := filepath.Base(ctx.MetadataDir)

	// Load or initialize session state
	state, err := s.loadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	// Initialize if state is nil OR BaseCommit is empty (can happen with partial state from warnings)
	if state == nil || state.BaseCommit == "" {
		agentType := resolveAgentType(ctx.AgentType, state)
		state, err = s.initializeSession(repo, sessionID, agentType, "", "") // No transcript/prompt in fallback
		if err != nil {
			return fmt.Errorf("failed to initialize session: %w", err)
		}
	}

	// Check if HEAD has changed (e.g., Claude did a rebase via tool call) and migrate if needed
	if err := s.migrateAndPersistIfNeeded(repo, state); err != nil {
		return err
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Check if shadow branch exists to report whether we created it
	shadowBranchName := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
	branchExisted := store.ShadowBranchExists(state.BaseCommit, state.WorktreeID)

	// Use the pending attribution calculated at prompt start (in InitializeSession)
	// This was calculated BEFORE the agent made changes, so it accurately captures user edits
	var promptAttr PromptAttribution
	if state.PendingPromptAttribution != nil {
		promptAttr = *state.PendingPromptAttribution
		state.PendingPromptAttribution = nil // Clear after use
	} else {
		// No pending attribution (e.g., first checkpoint or session initialized without it)
		promptAttr = PromptAttribution{CheckpointNumber: state.StepCount + 1}
	}

	// Log the prompt attribution for debugging
	attrLogCtx := logging.WithComponent(context.Background(), "attribution")
	logging.Debug(attrLogCtx, "prompt attribution at checkpoint save",
		slog.Int("checkpoint_number", promptAttr.CheckpointNumber),
		slog.Int("user_added", promptAttr.UserLinesAdded),
		slog.Int("user_removed", promptAttr.UserLinesRemoved),
		slog.Int("agent_added", promptAttr.AgentLinesAdded),
		slog.Int("agent_removed", promptAttr.AgentLinesRemoved),
		slog.String("session_id", sessionID))

	// Use WriteTemporary to create the checkpoint
	isFirstCheckpointOfSession := state.StepCount == 0
	result, err := store.WriteTemporary(context.Background(), checkpoint.WriteTemporaryOptions{
		SessionID:         sessionID,
		BaseCommit:        state.BaseCommit,
		WorktreeID:        state.WorktreeID,
		ModifiedFiles:     ctx.ModifiedFiles,
		NewFiles:          ctx.NewFiles,
		DeletedFiles:      ctx.DeletedFiles,
		MetadataDir:       ctx.MetadataDir,
		MetadataDirAbs:    ctx.MetadataDirAbs,
		CommitMessage:     ctx.CommitMessage,
		AuthorName:        ctx.AuthorName,
		AuthorEmail:       ctx.AuthorEmail,
		IsFirstCheckpoint: isFirstCheckpointOfSession,
	})
	if err != nil {
		return fmt.Errorf("failed to write temporary checkpoint: %w", err)
	}

	// If checkpoint was skipped due to deduplication (no changes), return early
	if result.Skipped {
		logCtx := logging.WithComponent(context.Background(), "checkpoint")
		logging.Info(logCtx, "checkpoint skipped (no changes)",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_type", "session"),
			slog.Int("checkpoint_count", state.StepCount),
			slog.String("shadow_branch", shadowBranchName),
		)
		fmt.Fprintf(os.Stderr, "Skipped checkpoint (no changes since last checkpoint)\n")
		return nil
	}

	// Update session state
	state.StepCount++

	// Note: LastCheckpointID is intentionally NOT cleared here.
	// It is set during condensation and used by handleAmendCommitMsg
	// to restore checkpoint trailers on amend operations.

	// Store the prompt attribution we calculated before saving

func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit, opts.WorktreeID)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	var allDeletedFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint, capture all changed files (modified tracked + untracked)
		// using `git status --porcelain -z` which respects both repo and global .gitignore.
		// This is much faster than filesystem walk. The base tree from HEAD already contains
		// all unchanged tracked files. We also capture user's pre-existing deletions.
		result, err := collectChangedFiles(ctx, s.repo)
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect changed files: %w", err)
		}
		allFiles = result.Changed
		// Merge user's pre-existing deletions with agent's deletions
		allDeletedFiles = result.Deleted
		allDeletedFiles = append(allDeletedFiles, opts.DeletedFiles...)
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
		allDeletedFiles = opts.DeletedFiles
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, allDeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := trailers.FormatShadowCommit(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
// worktreeID should be empty for main worktree or the internal git worktree name for linked worktrees.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit, worktreeID string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit, worktreeID)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

// Skip during rebase, cherry-pick, or revert operations
// These are replaying existing commits and should not be linked to agent sessions
if isGitSequenceOperation() {
	logging.Debug(logCtx, "prepare-commit-msg: skipped during git sequence operation",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
	)
	return nil
}

// Skip for merge and squash sources
// These are auto-generated messages - not from Claude sessions
switch source {
case "merge", "squash":
	logging.Debug(logCtx, "prepare-commit-msg: skipped for source",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
	)
	return nil
}

// Handle amend (source="commit") separately: preserve or restore trailer
if source == "commit" {
	return s.handleAmendCommitMsg(logCtx, commitMsgFile)
}

repo, err := OpenRepository()
if err != nil {
	return nil //nolint:nilerr // Hook must be silent on failure
}

worktreePath, err := GetWorktreePath()
if err != nil {
	return nil //nolint:nilerr // Hook must be silent on failure
}

// Find all active sessions for this worktree
// We match by worktree (not BaseCommit) because the user may have made
// intermediate commits without entering new prompts, causing HEAD to diverge
sessions, err := s.findSessionsForWorktree(worktreePath)
if err != nil || len(sessions) == 0 {
	// No active sessions or error listing - silently skip (hooks must be resilient)
	logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
	)
	return nil //nolint:nilerr // Intentional: hooks must be silent on failure
}

// Fast path: when an agent is committing (ACTIVE session + no TTY), skip
// content detection and interactive prompts. The agent can't respond to TTY
// prompts and the content detection can miss mid-session work (no shadow
// branch yet, transcript analysis may fail). Generate a checkpoint ID and
// add the trailer directly.
if !hasTTY() {
	for _, state := range sessions {
		if state.Phase.IsActive() {
			return s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source)
		}
	}

