func (r *ClaudeCodeRunner) RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error) {
	return r.RunPromptWithTools(ctx, workDir, prompt, r.AllowedTools)
}

func (r *ClaudeCodeRunner) RunPromptWithTools(ctx context.Context, workDir string, prompt string, tools []string) (*AgentResult, error) {
	// Build command: claude --model <model> -p "<prompt>" --allowedTools <tools>
	args := []string{
		"--model", r.Model,
		"-p", prompt,
	}

	if len(tools) > 0 {
		// Claude CLI expects each tool as a separate argument after --allowedTools
		// e.g., --allowedTools Edit Read Bash (not --allowedTools "Edit,Read,Bash")
		args = append(args, "--allowedTools")
		args = append(args, tools...)
	}

	// Create context with timeout
	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
	defer cancel()

	//nolint:gosec // args are constructed from trusted config, not user input
	cmd := exec.CommandContext(ctx, "claude", args...)
	cmd.Dir = workDir

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	start := time.Now()
	err := cmd.Run()
	duration := time.Since(start)

	result := &AgentResult{
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
		Duration: duration,
	}

	if err != nil {
		exitErr := &exec.ExitError{}
		if errors.As(err, &exitErr) {
			result.ExitCode = exitErr.ExitCode()
		} else {
			result.ExitCode = -1
		}
		//nolint:wrapcheck // error is from exec.Run, caller can check ExitCode in result
		return result, err
	}

	result.ExitCode = 0
	return result, nil
}

// GeminiCLIRunner implements AgentRunner for Gemini CLI.
// This is a placeholder for future implementation.
type GeminiCLIRunner struct {
	Timeout time.Duration
}

// NewGeminiCLIRunner creates a new Gemini CLI runner with the given config.
func NewGeminiCLIRunner(config AgentRunnerConfig) *GeminiCLIRunner {
	timeout := config.Timeout
	if timeout == 0 {
		timeout = 2 * time.Minute
	}

	return &GeminiCLIRunner{
		Timeout: timeout,
	}
}

func (r *GeminiCLIRunner) Name() string {
	return AgentNameGeminiCLI
}

// IsAvailable checks if Gemini CLI is installed and authenticated.
func (r *GeminiCLIRunner) IsAvailable() (bool, error) {
	// Check if gemini CLI is in PATH
	if _, err := exec.LookPath("gemini"); err != nil {
		return false, fmt.Errorf("gemini CLI not found in PATH: %w", err)
	}

	// Check if gemini is working
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "gemini", "--version")
	if err := cmd.Run(); err != nil {
		return false, fmt.Errorf("gemini CLI not working: %w", err)
	}

	return true, nil
}

func (r *GeminiCLIRunner) RunPrompt(ctx context.Context, workDir string, prompt string) (*AgentResult, error) {
	return r.RunPromptWithTools(ctx, workDir, prompt, nil)
}

func (s *ManualCommitStrategy) initializeSession(repo *git.Repository, sessionID string, agentType agent.AgentType, transcriptPath string, userPrompt string) (*SessionState, error) {
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	worktreePath, err := GetWorktreePath()
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree path: %w", err)
	}

	// Get worktree ID for shadow branch naming
	worktreeID, err := paths.GetWorktreeID(worktreePath)
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree ID: %w", err)
	}

	// Capture untracked files at session start to preserve them during rewind
	untrackedFiles, err := collectUntrackedFiles()
	if err != nil {
		// Non-fatal: continue even if we can't collect untracked files
		untrackedFiles = nil
	}

	// Generate TurnID for the first turn
	turnID, err := id.Generate()
	if err != nil {
		return nil, fmt.Errorf("failed to generate turn ID: %w", err)
	}

	now := time.Now()
	headHash := head.Hash().String()
	state := &SessionState{
		SessionID:             sessionID,
		CLIVersion:            buildinfo.Version,
		BaseCommit:            headHash,
		AttributionBaseCommit: headHash,
		WorktreePath:          worktreePath,
		WorktreeID:            worktreeID,
		StartedAt:             now,
		LastInteractionTime:   &now,
		TurnID:                turnID.String(),
		StepCount:             0,
		UntrackedFilesAtStart: untrackedFiles,
		AgentType:             agentType,
		TranscriptPath:        transcriptPath,
		FirstPrompt:           truncatePromptForStorage(userPrompt),
	}

	if err := s.saveSessionState(state); err != nil {
		return nil, err
	}

	return state, nil
}

// getShadowBranchNameForCommit returns the shadow branch name for the given base commit and worktree ID.
// worktreeID should be empty for the main worktree or the internal git worktree name for linked worktrees.
func getShadowBranchNameForCommit(baseCommit, worktreeID string) string {
	return checkpoint.ShadowBranchNameForCommit(baseCommit, worktreeID)
}

