// DebugSessionState logs information about session state files and shadow branches.
// Used for debugging test failures.
func (env *TestEnv) DebugSessionState() {
	env.T.Helper()

	// List session state files
	sessionDir := filepath.Join(env.RepoDir, ".git", "entire-sessions")
	entries, err := os.ReadDir(sessionDir)
	if err != nil {
		env.T.Logf("DEBUG: No session state dir or error: %v", err)
	} else {
		env.T.Logf("DEBUG: Session state files in %s:", sessionDir)
		for _, e := range entries {
			if strings.HasSuffix(e.Name(), ".json") {
				content, readErr := os.ReadFile(filepath.Join(sessionDir, e.Name()))
				if readErr != nil {
					env.T.Logf("  - %s (error reading: %v)", e.Name(), readErr)
				} else {
					var state map[string]any
					if err := json.Unmarshal(content, &state); err == nil {
						env.T.Logf("  - %s: BaseCommit=%v, Phase=%v, FilesTouched=%v",
							e.Name(),
							state["base_commit"],
							state["phase"],
							state["files_touched"])
					} else {
						env.T.Logf("  - %s (parse error: %v)", e.Name(), err)
					}
				}
