// - User commits ALL (B, C, D, E) together
// - All files link to single checkpoint
func TestE2E_Scenario6_StashSecondPromptUnstashCommitAll(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t, "manual-commit")

