// SimulateAgentSession manually invokes Entire hooks to simulate an agent session.
// This is used when Claude CLI doesn't invoke hooks (e.g., for subsequent prompts).
// The sessionID should be a unique UUID. The modifiedFiles are files the agent "touched".
func (env *TestEnv) SimulateAgentSession(sessionID string, modifiedFiles []string) {
	env.T.Helper()

	// Build metadata path matching what hooks expect
	metadataDir := filepath.Join(".entire", "metadata", sessionID)

	// 1. Session start hook
	//nolint:gosec,noctx // test code
	startCmd := exec.Command(getTestBinary(), "hooks", "claude-code", "session-start")
	startCmd.Dir = env.RepoDir
	startCmd.Env = append(os.Environ(),
		"CLAUDE_SESSION_ID="+sessionID,
	)
	if output, err := startCmd.CombinedOutput(); err != nil {
		env.T.Logf("session-start hook failed: %v\nOutput: %s", err, output)
	}

	// 2. User prompt submit hook (initializes session state)
	//nolint:gosec,noctx // test code
	promptCmd := exec.Command(getTestBinary(), "hooks", "claude-code", "user-prompt-submit")
	promptCmd.Dir = env.RepoDir
	promptCmd.Env = append(os.Environ(),
		"CLAUDE_SESSION_ID="+sessionID,
		"CLAUDE_TRANSCRIPT_PATH="+filepath.Join(metadataDir, "full.jsonl"),
	)
	if output, err := promptCmd.CombinedOutput(); err != nil {
		env.T.Logf("user-prompt-submit hook failed: %v\nOutput: %s", err, output)
	}

	// Create minimal transcript file for the simulated session
	transcriptDir := filepath.Join(env.RepoDir, metadataDir)
	if err := os.MkdirAll(transcriptDir, 0o750); err != nil {
		env.T.Fatalf("failed to create metadata dir: %v", err)
	}
	// Create a minimal JSONL transcript that mentions the files
	transcriptContent := ""
	for _, file := range modifiedFiles {
		transcriptContent += fmt.Sprintf(`{"type":"assistant","text":"Creating file %s"}%s`, file, "\n")
	}
	if err := os.WriteFile(filepath.Join(transcriptDir, "full.jsonl"), []byte(transcriptContent), 0o600); err != nil {
		env.T.Fatalf("failed to write transcript: %v", err)
	}
	// Create prompt file
	promptContent := "Simulated prompt for files: " + strings.Join(modifiedFiles, ", ")
	if err := os.WriteFile(filepath.Join(transcriptDir, "prompt.txt"), []byte(promptContent), 0o600); err != nil {
		env.T.Fatalf("failed to write prompt: %v", err)
	}

	// 3. Stop hook (saves checkpoint, marks session as ended)
	//nolint:gosec,noctx // test code
	stopCmd := exec.Command(getTestBinary(), "hooks", "claude-code", "stop")
	stopCmd.Dir = env.RepoDir
	stopCmd.Env = append(os.Environ(),
		"CLAUDE_SESSION_ID="+sessionID,
		"CLAUDE_TRANSCRIPT_PATH="+filepath.Join(metadataDir, "full.jsonl"),
	)
	if output, err := stopCmd.CombinedOutput(); err != nil {
		env.T.Logf("stop hook failed: %v\nOutput: %s", err, output)
