}

// DebugSessionState logs information about session state files and shadow branches.
// Used for debugging test failures.
func (env *TestEnv) DebugSessionState() {
	env.T.Helper()

	// List session state files
	sessionDir := filepath.Join(env.RepoDir, ".git", "entire-sessions")
	entries, err := os.ReadDir(sessionDir)
	if err != nil {
		env.T.Logf("DEBUG: No session state dir or error: %v", err)
	} else {
		env.T.Logf("DEBUG: Session state files in %s:", sessionDir)
		for _, e := range entries {
			if strings.HasSuffix(e.Name(), ".json") {
				content, readErr := os.ReadFile(filepath.Join(sessionDir, e.Name()))
				if readErr != nil {
					env.T.Logf("  - %s (error reading: %v)", e.Name(), readErr)
				} else {
					var state map[string]any
					if err := json.Unmarshal(content, &state); err == nil {
						env.T.Logf("  - %s: BaseCommit=%v, Phase=%v, FilesTouched=%v",
							e.Name(),
							state["base_commit"],
							state["phase"],
							state["files_touched"])
					} else {
						env.T.Logf("  - %s (parse error: %v)", e.Name(), err)
					}
				}
			}
		}
	}

	// List shadow branches
	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		env.T.Logf("DEBUG: Failed to open repo: %v", err)
		return
	}

	refs, err := repo.References()
	if err != nil {
		env.T.Logf("DEBUG: Failed to list refs: %v", err)
		return
	}

	env.T.Log("DEBUG: Shadow branches:")
	//nolint:errcheck // ForEach callback doesn't return errors we need to handle
	refs.ForEach(func(ref *plumbing.Reference) error {
		name := ref.Name().String()
		if strings.HasPrefix(name, "refs/heads/entire/") && !strings.Contains(name, "checkpoints") {
			// Get tree contents
			commit, err := repo.CommitObject(ref.Hash())
			if err != nil {
				env.T.Logf("  - %s (error: %v)", name, err)
				return nil
			}
			tree, err := commit.Tree()
			if err != nil {
				env.T.Logf("  - %s (tree error: %v)", name, err)
				return nil
			}
			var files []string
			//nolint:errcheck // Just collecting file names
			tree.Files().ForEach(func(f *object.File) error {
				files = append(files, f.Name)
				return nil
			})
			env.T.Logf("  - %s: files=%v", strings.TrimPrefix(name, "refs/heads/"), files)
		}
		return nil
	})
}

