		})
		// The A commit has full prompt 1 transcript (A, B, C were all created)
		env.ValidateCheckpoint(CheckpointValidation{
			CheckpointID:              checkpointIDs[1],
			Strategy:                  "manual-commit",
			FilesTouched:              []string{"combo_a.go"},
