	//nolint:noctx // test code, no context needed for git stash pop
	cmd := exec.Command("git", "stash", "pop")
	cmd.Dir = env.RepoDir
	if output, err := cmd.CombinedOutput(); err != nil {
		env.T.Fatalf("git stash pop failed: %v\nOutput: %s", err, output)
